<template>
  <div class="space-y-5">
    <div class="breadcrumbs text-sm"><ul><li><NuxtLink to="/spoc-submissions">SPOC workflow</NuxtLink></li><li>Agendas</li></ul></div>
    <header class="rounded-2xl border border-base-200 bg-base-100 p-5 shadow-sm"><div class="flex flex-wrap justify-between gap-3"><div><h1 class="text-2xl font-bold">SPOC agendas</h1><p class="text-sm text-base-content/60">Prepare either a private Round Robin review or a committee Sitting agenda.</p></div><button class="btn btn-primary btn-sm" @click="showCreate = true"><Icon name="lucide:plus" />Create agenda</button></div></header>
    <div class="overflow-x-auto rounded-2xl border border-base-200 bg-base-100"><table class="table"><thead><tr><th>Agenda</th><th>Mode</th><th>Schedule / deadline</th><th>Cases</th><th>Status</th><th /></tr></thead><tbody><tr v-for="agenda in agendas" :key="agenda.uuid"><td><p class="font-semibold">{{ agenda.title }}</p><p class="font-mono text-xs text-base-content/50">{{ agenda.agenda_number }}</p></td><td><span class="badge badge-outline">{{ label(agenda.mode) }}</span></td><td>{{ date(agenda.mode === 'SITTING' ? agenda.scheduled_at : agenda.decision_due_at) }}</td><td>{{ agenda.items_count }}</td><td><span class="badge badge-sm">{{ label(agenda.status) }}</span></td><td><NuxtLink :to="`/spoc-agendas/${agenda.uuid}`" class="btn btn-ghost btn-sm">Open</NuxtLink></td></tr><tr v-if="!agendas.length"><td colspan="6" class="py-12 text-center text-base-content/45">No SPOC agendas have been created.</td></tr></tbody></table></div>

    <dialog :class="['modal', showCreate && 'modal-open']"><div class="modal-box max-w-3xl"><h2 class="text-xl font-bold">Create SPOC agenda</h2><form class="mt-5 space-y-4" @submit.prevent="create"><input v-model="form.title" class="input w-full" placeholder="Agenda title" required /><div class="grid gap-3 sm:grid-cols-2"><label class="card cursor-pointer border p-4"><span class="flex gap-3"><input v-model="form.mode" type="radio" value="ROUND_ROBIN" class="radio radio-primary" /><span><b>Round Robin</b><small class="block text-base-content/55">Members review and decide independently.</small></span></span></label><label class="card cursor-pointer border p-4"><span class="flex gap-3"><input v-model="form.mode" type="radio" value="SITTING" class="radio radio-primary" /><span><b>Sitting</b><small class="block text-base-content/55">Cases presented in one committee meeting.</small></span></span></label></div><input v-if="form.mode === 'ROUND_ROBIN'" v-model="form.decision_due_at" type="datetime-local" class="input w-full" required /><input v-else v-model="form.scheduled_at" type="datetime-local" class="input w-full" required /><input v-if="form.mode === 'SITTING'" v-model="form.venue" class="input w-full" placeholder="Meeting venue" /><div><h3 class="mb-2 text-sm font-bold">Cases awaiting agenda</h3><label v-for="row in readyCases" :key="row.uuid" class="mb-2 flex cursor-pointer items-start gap-3 rounded-xl border border-base-200 p-3"><input v-model="form.submission_uuids" type="checkbox" :value="row.uuid" class="checkbox checkbox-primary checkbox-sm" /><span><b class="text-sm">{{ row.tender?.title }}</b><small class="block text-base-content/55">{{ row.reference_number }} · {{ row.tender?.company?.name }}</small></span></label><p v-if="!readyCases.length" class="text-sm text-base-content/50">There are no director-approved cases awaiting an agenda.</p></div><div class="modal-action"><button type="button" class="btn" @click="showCreate = false">Cancel</button><button class="btn btn-primary" :disabled="saving || !form.submission_uuids.length">Create draft agenda</button></div></form></div><form method="dialog" class="modal-backdrop"><button @click="showCreate = false">close</button></form></dialog>
  </div>
</template>
<script setup>
definePageMeta({ layout: 'default' }); useHead({ title: 'SPOC agendas' });
const api = useSpocWorkflowHelper(); const toast = useToast(); const agendas = ref([]); const readyCases = ref([]); const showCreate = ref(false); const saving = ref(false);
const form = reactive({ title: '', mode: 'ROUND_ROBIN', decision_due_at: '', scheduled_at: '', venue: '', submission_uuids: [] });
const label = value => String(value || '—').replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, c => c.toUpperCase()); const date = value => value ? new Date(value).toLocaleString('en-ZW') : '—';
const load = async () => { const [agendaResult, boardResult] = await Promise.all([api.agendas(), api.board()]); agendas.value = agendaResult.data?.data ?? []; readyCases.value = (boardResult.data?.data ?? []).filter(row => row.status === 'AWAITING_AGENDA'); };
const create = async () => { saving.value = true; const payload = { ...form, scheduled_at: form.mode === 'SITTING' ? form.scheduled_at : null, decision_due_at: form.mode === 'ROUND_ROBIN' ? form.decision_due_at : null }; const { data, error } = await api.createAgenda(payload); saving.value = false; if (error) return toast.error({ title: 'Could not create agenda', message: error?.data?.message }); showCreate.value = false; await navigateTo(`/spoc-agendas/${data.data.uuid}`); };
onMounted(load);
</script>
